import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        pts=[]
        for b,d in cam.get('walls',[]):
            a=math.radians(b+h)
            s=-d*math.cos(a)
            y=d*math.sin(a)
            if s>0.3:
                pts.append((s,y))
        mids=[]
        for q in (2.5,3.5,4.5):
            left=[(abs(s-q),y) for s,y in pts if y>0 and abs(s-q)<1.0]
            right=[(abs(s-q),y) for s,y in pts if y<0 and abs(s-q)<1.0]
            if left and right:
                yl=min(left)[1]; yr=min(right)[1]
                if 2.2<yl-yr<6.0:
                    mids.append((q,(yl+yr)/2))
        if mids:
            q,y=mids[-1]
            desired=max(-28,min(28,math.degrees(math.atan2(5.2*y,q*q))))
    steer=max(-34,min(34,2.4*h-1.8*desired))
    return (steer,-0.8,-23)

