 speed=-1.0 if abs(h)<25 else -0.65
 if o['t']-lastprint>10:
  lastprint=o['t']; print(json.dumps({'t':o['t'],'h':h,'desired':desired,'progress':o['progress'],'camera':cam}))
 return steer,speed,-41

